</style></head><body><div class="admin-shell"><aside class="sidebar" id="admin-sidebar"><a class="brand-lockup" href="/admin/"><span class="brand-mark">'.admin_svg('bolt').'</span><span class="brand-name">TDC Tech <span class="admin-badge">ADMIN</span></span></a><div class="side-profile"><span class="avatar">'.htmlspecialchars($initial,ENT_QUOTES,'UTF-8').'</span><span><strong>'.$safeName.'</strong><small>Administrator · Private panel</small></span></div><div class="side-label">Workspace</div><nav class="side-nav" aria-label="Admin navigation">';
