  echo '</nav><div class="sidebar-spacer"></div><div class="side-label">Platform</div><nav class="side-nav" aria-label="Site management"><a class="side-link'.($active==='content'?' active':'').'" href="/admin/content.php">'.admin_svg('globe').'<span>Website content</span></a><a class="side-link'.($active==='emails'?' active':'').'" href="/admin/emails.php">'.admin_svg('mail').'<span>Email notifications</span></a></nav><div class="side-divider"></div><button class="side-action danger" id="admin-logout" type="button">'.admin_svg('logout').'<span>Sign out</span></button></aside><div class="sidebar-scrim" id="sidebar-scrim"></div><main class="main"><header class="topbar"><button class="menu-toggle" id="menu-toggle" type="button" aria-label="Open admin navigation" aria-expanded="false">'.admin_svg('menu').'</button><div class="crumb">TDC TECH <span aria-hidden="true">/</span> <strong>'.$safeTitle.'</strong></div><div class="top-user"><span class="avatar">'.htmlspecialchars($initial,ENT_QUOTES,'UTF-8').'</span><span>'.$safeName.'</span></div></header><div class="page-wrap"><div class="page-heading"><div><span class="eyebrow">Admin control center</span><h1>'.$safeTitle.'</h1><p>Track every service, customer, order, payment, and platform operation.</p></div></div><div class="notice" id="notice" role="status"></div>';
  echo '<script>(function(){const side=document.getElementById("admin-sidebar"),scrim=document.getElementById("sidebar-scrim"),toggle=document.getElementById("menu-toggle");function close(){side.classList.remove("open");scrim.classList.remove("visible");toggle.setAttribute("aria-expanded","false")}toggle.addEventListener("click",()=>{const open=side.classList.toggle("open");scrim.classList.toggle("visible",open);toggle.setAttribute("aria-expanded",String(open))});scrim.addEventListener("click",close);document.addEventListener("keydown",e=>{if(e.key==="Escape")close()});document.querySelectorAll(".side-link").forEach(a=>a.addEventListener("click",close));document.getElementById("admin-logout").addEventListener("click",async()=>{const c=await fetch("/api/csrf.php",{credentials:"same-origin"}).then(r=>r.json());await fetch("/api/auth.php",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":c.csrf},body:JSON.stringify({action:"logout"})});location.href="/admin/login.php"})})();</script>';
